/* ═══════════════════════════════════════════════════════════════
   🚌 버스 저지 (Bus blockade)
   간담회로도 달래지지 않은 서포터들이 경기 뒤 구단 버스 앞을 막아선다.
   K리그에서 실제로 벌어지는 장면이다. 여기서의 선택은 라커룸과 팬 여론을
   동시에 흔든다 — 도망치면 선수들이 등을 돌리고, 맞서면 팬이 더 격해진다.
   ═══════════════════════════════════════════════════════════════ */
const BUS_GAP=4;                    // 최소 이 라운드 간격
let busCtx=null;
function shouldTriggerBusBlock(){
  const t=userTeam();
  if(!t || G.phase!=="league") return false;
  if(!G.townhall) return false;                      // 간담회를 한 번은 겪은 뒤에 벌어진다
  const rd=t.div===1?G.r1:G.r2;
  if(rd - G.townhall.rd < 2) return false;           // 간담회 직후는 아니다
  const last=G.busBlock||null;
  if(last && rd-last.rd < BUS_GAP) return false;
  // 간담회 이후로도 반등하지 못했는가
  const since=t.form.slice(-(rd-G.townhall.rd));
  const wins=since.filter(f=>f==="W").length;
  if(wins>0) return false;                           // 한 번이라도 이겼으면 넘어간다
  const fans=(G.trust&&G.trust.fans)||50;
  const lose=fanLoseStreakLen(t), winless=fanWinlessStreakLen(t);
  const bad = lose>=3 || winless>=5;
  if(!bad) return false;
  if(fans>=42) return false;                         // 팬 신뢰가 아직 버텨 준다
  G.busBlock={rd, n:Math.max(lose,winless)};
  return true;
}
