function showBusBlock(M, cont){
  busCtx={M, cont, phase:"choose"};
  $("#advBtn").disabled=true;
  VIEW="match";
  document.querySelectorAll(".navbtn").forEach(b=>b.classList.toggle("on",b.dataset.v==="match"));
  renderBusBlock();
}
function renderBusBlock(){
  if(!busCtx) return;
  const t=userTeam();
  const info=fanTownhallStreakInfo(t);
  const n=(G.busBlock&&G.busBlock.n)||info.n;
  const btns=BUS_OPTS.map((o,i)=>`<button class="mini" style="display:block;width:100%;text-align:left;margin-bottom:6px;padding:10px"
    onclick="busPick(${i})">${o.t}</button>`).join("");
  $("#main").innerHTML=`<h2>🚌 구단 버스가 막혔습니다</h2>
  <div class="card stCard" style="border-color:var(--red)">
    <div class="msg warn" style="font-size:15px">
      경기 종료 후 주차장. 서포터 수십 명이 구단 버스 앞을 가로막았습니다.</div>
    <div class="stSay">📣 서포터: "내려와! 얼굴 좀 보자!"<br>
      📣 서포터: "${info.kind==='lose'?`${n}연패`:`${n}경기 무승`}가 말이 됩니까!"<br>
      📣 서포터: "간담회 때 뭐라고 했는지 기억은 하십니까?"</div>
    <p class="small" style="margin-top:8px">선수들이 버스 안에서 창밖을 보고 있습니다.
      지금 감독이 어떻게 하느냐를 <b style="color:#fff;font-weight:800">스물여섯 명이 전부 보고 있습니다.</b></p>
  </div>
  <div class="card stCard"><h3>어떻게 하시겠습니까?</h3>${btns}</div>`;
  window.scrollTo(0,0);
}
function busPick(i){
  const o=BUS_OPTS[i]; if(!o||!busCtx) return;
  const t=userTeam();
  // 선수단 호감도·사기
  for(const p of t.players) affAdd(p, o.af, "버스 저지");
  t.morale=Math.round(clamp(t.morale+o.mor,35,99)*100)/100;
  adjustTrust("fans", o.fan, "버스 저지 대응");
  adjustTrust("owner", o.own, "버스 저지 대응");
  // 팬 여론
  const v={t:t.short};
  const map={shield:[SOC.busShield,FMK.busShield,1], provoke:[SOC.busProvoke,FMK.busProvoke,-1],
             flee:[SOC.busFlee,FMK.busFlee,-1], plan:[SOC.busPlan,null,0],
             bow:[SOC.busPlan,null,0], money:[SOC.busPlan,null,0], talk:[SOC.busPlan,null,1], cold:[SOC.busProvoke,null,-1]};
  const m=map[o.soc]||map.bow;
  if(m[0]) socialFill(m[0], 3+R(2), m[2], v);
  if(m[1]) fmkFill(m[1], 3+R(2), v);
  addMood(`🚌 경기 후 버스 저지 — ${o.t.replace(/^[^ ]+ /,"")}`);
  staffLog(`서포터 버스 저지 대응 — ${o.t.replace(/^[^ ]+ /,"")}`);
  const cls = o.af>=6 ? "good" : o.af>=0 ? "info" : "warn";
  const cont=busCtx.cont;
  busCtx=null;
  $("#main").innerHTML=`<h2>🚌 구단 버스가 막혔습니다</h2>
  <div class="card stCard">
    <p>🗣️ 감독: <b>${o.t.replace(/^[^ ]+ /,"")}</b></p>
    <p style="color:var(--acc)">📣 ${o.fanSay}</p>
    <p class="small">🚌 ${o.sqSay}</p>
    <div class="msg ${cls}">선수단 호감도 ${o.af>0?"+":""}${o.af} · 팀 사기 ${o.mor>0?"+":""}${o.mor}
      · 서포터 신뢰 ${o.fan>0?"+":""}${o.fan} · 구단주 신뢰 ${o.own>0?"+":""}${o.own}</div>
  </div>
  <div class="card"><button class="mini" style="width:100%;padding:11px" onclick="busDone()">버스가 출발합니다 ▶</button></div>`;
  BUS_CONT=cont;
  saveGame(); window.scrollTo(0,0);
}
let BUS_CONT=null;
function busDone(){
  const c=BUS_CONT; BUS_CONT=null;
  if(c) c(); else { $("#advBtn").disabled=false; show("home"); }
}
/* ═══════════════════════════════════════════════════════════════
   🙅 이적 거부와 설득
   예전에는 "야심가면 60% 거부" 정도의 단순 판정이었다. 지금은 선수가 이적을 놓고
   실제로 따져 볼 만한 것들을 전부 본다 — 가는 팀의 수준, 나를 쓰는 감독,
   지금 뛰고 있는지, 나이와 남은 계약, 그리고 이 팀에 정이 붙었는지.
   거부당해도 한 번은 붙잡고 설득할 수 있다. 실패하면 관계에 금이 간다.
   ═══════════════════════════════════════════════════════════════ */
/* ⚠ 제보 — 「성사 전망이 순조로움인데 선수가 이적을 거부한다」.
   화면 라벨(성격·불만·전력차로 대충 판정)과 실제 판정(moveRefusal)이 서로 다른 계산이었다.
   ─ 마음의 크기(want)를 한 곳에서만 만들고, 화면도 판정도 이 값을 쓴다. */
function moveWant(p, buyer){
  const ut=userTeam();
  const gap=teamOVR(buyer)-teamOVR(ut);        // +면 더 좋은 팀으로 간다
  const age=G.season-p.by;
  const share=playShare(p);
  const A=aff(p);
  let want = 66;                               // 떠나고 싶은 마음 (0~100). 기본 58 → 66 (거부가 잦다는 제보)
  want += gap*6;                               // 더 좋은 팀이면 끌린다
  want += (A-50)*-0.55;                        // 감독을 좋아하면 남고 싶다
  want += (p.unhappy||0)*18;                   // 불만이 있으면 떠나고 싶다
  want += p.sulk>0 ? 25 : 0;
  want -= share*19;                            // 주전으로 뛰고 있으면 굳이
  want += (p.pers===1?14 : p.pers===2?-10 : p.pers===3?4 : 0);   // 야심가는 늘 위를 본다
  if(age>=31) want += 8;                       // 마지막 계약을 노린다
  if(age<=21) want -= 10;                      // 어린 선수는 익숙한 곳을 선호
  if((p.ct||1)<=1) want += 12;                 // 계약이 얼마 안 남았다
  if(p.noMove) want -= 45;                     // 잔류 선언
  /* ⚠ 제보 — 「본인이 이적을 요청해 놓고 정작 제의가 오면 거절한다」.
     공개 이적 요청은 「나를 내보내 달라」는 선언이다. 그래 놓고 마음이 바뀌면
     감독 입장에서는 손쓸 방법이 없다. 요청 중에는 웬만하면 간다.
     ─ 다만 지금 있는 곳보다 확실히 못한 팀이면 그때는 재고할 수 있다. */
  const _wlv=wantsOutLv(p);
  if(_wlv>0){
    /* 단계가 낮으면 「알아봐 달라」, 높으면 「보내 달라」 — 그래도 회의에서 이적 요청으로
       보고된 선수는 협상에서도 최소한 이야기는 듣는다 (제보: 말과 행동이 어긋남) */
    want=Math.max(want, (gap>=-4 ? 92 : 74) - (3-_wlv)*7);
    if(p.sulk>0) want=Math.max(want, 95);      // 태업까지 간 선수는 붙잡을 수 없다
  }
  return clamp(want, 2, 98);
}
/* 🚪 감독이 이적을 허락한 상태로 표시한다.
   ⚠ 제보 — 「이적 요청 → 감독이 허용 → 제의 수락 → 선수가 또 거부」.
     허용 처리(면담·스태프 회의)가 불만 수치를 내리거나 지우는데, 「떠나고 싶다」 판정이
     바로 그 불만 수치에 매달려 있었다. 허락하는 순간 wantsOut 이 false 가 되어
     개인 협상에서 다시 거부당하는, 감독이 손쓸 수 없는 고리가 생겼다.
   ─ 「보내 주기로 했다」는 사실 자체를 따로 들고 있는다. 그 시즌 동안 유효하다. */
function allowOut(p, why){
  if(!p) return;
  p.okOut={s:G.season, why:why||"이적 허용"};
}
function clearAllowOut(p){ if(p) delete p.okOut; }
function allowedOut(p){ return !!(p && p.okOut && p.okOut.s===G.season && !p.noMove); }
/* 지금 「내보내 달라」고 말하고 있는 상태인가
   ⚠ 제보 원문 — 「선수 팔때 타구단 협상하고 설득해도 안간다 태업하고 불만표출 하는데
      동시에 스태프회의에는 그 선수가 새로운도전을 원한다 이적을 알아봐달라 라고 올라옵니다..」
   원인: 스태프 회의는 「불만 1단계 이상 + 사유가 이적 요청」이면 안건으로 올린다(staffAgenda·
   grieveKey). 그런데 여기서는 「3단계」를 요구했다. 이적설로 붙은 1~2단계 이적 요청은
   회의에서는 "이적을 알아봐 달라"고 말하면서, 실제 협상에서는 남고 싶다고 거절하는
   앞뒤가 안 맞는 상태가 됐다.
   ─ 두 곳이 같은 것을 보게 한다. 단계는 「얼마나 절실한가」로만 쓴다(wantsOutLv). */
function wantsOutLv(p){
  if(!p || p.noMove) return 0;
  if(allowedOut(p)) return 3;                          // 감독이 이미 보내 주기로 했다
  if(!String(p.uWhy||"").includes("이적 요청")) return 0;
  return clamp(Math.round(p.unhappy||0), 0, 3);
}
function wantsOut(p){ return wantsOutLv(p)>0; }
/* 거부 확률(%) — 화면에 그대로 보여 준다 */
function moveRefuseP(p, buyer){ return Math.round(100-moveWant(p, buyer)); }
/* 협상 화면에 띄울 한 줄 — 이 선수가 지금 어떤 마음인지 */
function moveMoodLine(p, buyer){
  if(!p) return "";
  {
    const lv=wantsOutLv(p);
    if(lv>0) return lv>=3
      ? `🚪 <b>본인이 이적을 요청한 상태</b>입니다 — 웬만한 조건이면 받아들입니다.`
      : `🚪 <b>새 도전을 원하고 있습니다</b> (요청 ${lv}/3) — 이야기를 들어 볼 마음이 있습니다. (거절 가능성 ${moveRefuseP(p, buyer)}%)`;
  }
  if(p.noMove)    return `🛡️ <b>잔류를 선언한 선수</b>입니다 — 설득이 매우 어렵습니다.`;
  const r=moveRefuseP(p, buyer);
  return r>=55 ? `🙅 지금 팀에 만족하고 있습니다 (거절 가능성 ${r}%)`
       : r>=30 ? `🤔 마음이 반반입니다 (거절 가능성 ${r}%)`
               : `🙂 이야기는 들어 볼 생각입니다 (거절 가능성 ${r}%)`;
}
function moveRefusal(p, buyer){
  const ut=userTeam();
  const gap=teamOVR(buyer)-teamOVR(ut);
  const age=G.season-p.by;
  const share=playShare(p);
  const A=aff(p);
  const want=moveWant(p, buyer);
  const refuse = Math.random()*100 > want;
  let why="cond";
  if(p.noMove) why="noMove";
  else if(gap<-0.5) why="down";                // 전력이 떨어지는 팀
  else if(A>=68) why="loyal";                  // 감독이 좋아서
  else if(share>=0.75) why="playing";          // 여기서 잘 뛰고 있어서
  else if(age<=21) why="young";
  return {refuse, want:Math.round(want), why};
}
const REF_SAY={
  noMove:p=>`"말씀드렸잖습니까. 저는 아무 데도 안 갑니다."`,
  down:(p,b)=>`"${b.short}요? 죄송하지만 제 커리어를 거기서 마무리할 생각은 없습니다."`,
  loyal:p=>`"감독님 밑에서 더 배우고 싶습니다. 지금 떠나고 싶지 않아요."`,
  playing:p=>`"여기서 매주 뛰고 있습니다. 굳이 왜 옮겨야 하죠?"`,
  young:p=>`"아직 이 팀에서 보여드릴 게 남았습니다."`,
  cond:(p,b)=>`"${b.short}행이라... 지금은 마음이 없습니다."`
};FRIV.slapBad=[
 ["{t} 감독 폭행 사건 ㄷㄷ 리그가 시끄럽다",-1],
 ["이런 걸로 K리그 검색어 올라가는 게 제일 싫다",-1],
 ["{p} 선수한테 잘못한 거지 뭐",-1],
 ["감독들 다 조심해라 진짜",-1]];
FRIV.refSlap=[
 ["{t} 감독 심판 폭행 ㄷㄷㄷ 이건 리그 역사급 사건",-1],
 ["K리그 세계 뉴스 진출 (나쁜 쪽으로)",-1],
 ["{r} 주심 병원 이송됐다던데... 쾌유 빈다",-1],
 ["이건 팬심 떠나서 그냥 범죄지",-1],
 ["{t} 프런트 지금 밤샘 비상회의 중일 듯",-1],
 ["솔직히 오늘 그 판정은 나도 화났음. 근데 때리면 끝인 거야",0]];

/* 설득 카드 — k: 판정 보정, aff: 실패 시 호감도 대가 */
const PERSUADE=[
  {t:"이 이적이 네 커리어에 더 좋다고 설득한다", k:{down:-15, loyal:8, playing:10, young:12, cond:10}, af:-4,
   ok:p=>`"...그렇게 말씀하시니 생각이 좀 달라지네요. 가보겠습니다."`,
   no:p=>`"제 커리어는 제가 압니다, 감독님."`},
  {t:"솔직히 우리 팀 계획에 네 자리는 없다고 말한다", k:{down:12, loyal:-8, playing:-12, young:-5, cond:14}, af:-14,
   ok:p=>`"...알겠습니다. 그렇게까지 말씀하시면 제가 나가야죠."`,
   no:p=>`"그럼 벤치에 앉아 있겠습니다. 계약은 제 권리니까요."`},
  {t:"좋은 조건을 받아냈다며 개인 조건을 설명한다", k:{down:14, loyal:6, playing:8, young:6, cond:12}, af:-3,
   ok:p=>`"조건이 그 정도라면... 가족과 이야기해 보겠습니다. 좋습니다."`,
   no:p=>`"돈 문제가 아닙니다, 감독님."`},
  {t:"그동안 고마웠다며 좋게 보내주고 싶다고 말한다", k:{down:6, loyal:16, playing:4, young:10, cond:8}, af:+2,
   ok:p=>`"...감독님이 그렇게까지 말씀하시니. 좋은 기억으로 남기겠습니다."`,
   no:p=>`"마음은 감사합니다. 그래도 저는 남고 싶습니다."`}
];
let PERSU=null;
function openPersuade(pid, tid, fee, swapPid, why){
  /* 🔙 제보 — 설득이 끝나도 「지금 보고 있던 탭」으로 돌아온다 (예전에는 늘 제의 탭으로 튕겼다) */
  PERSU={pid, tid, fee, swapPid, why, done:false, back:(function(){ try{ return negoStay(); }catch(e){ return "offers"; } })()};
  renderPersuade();
}
function persuadeBack(){ try{ return (PERSU && PERSU.back==="nego") ? "nego" : "offers"; }catch(e){ return "offers"; } }
function renderPersuade(){
  const P=PERSU; if(!P) return;
  const t=userTeam(), p=t.players.find(x=>x.id===P.pid), b=G.teams[P.tid];
  if(!p||!b){ const _b=persuadeBack(); PERSU=null; return show(_b); }
  const A=affLabel(aff(p));
  const sulkRisk=(o)=> (o.af<=-10) && (p.pers===3 || (p.unhappy||0)>=2 || (p._persFail||0)>=1);
  const btns=PERSUADE.map((o,i)=>`<button class="mini" style="display:block;width:100%;text-align:left;margin-bottom:6px;padding:9px${sulkRisk(o)?";border-color:var(--red)":""}"
    onclick="persuadePick(${i})">${o.t}<div class="small" style="opacity:.7;margin-top:2px">실패 시 호감도 ${o.af>0?"+":""}${o.af}${sulkRisk(o)?' · <span style="color:var(--red)">태업 위험</span>':""}</div></button>`).join("");
  $("#main").innerHTML=`<h2>🤝 이적 설득 — ${p.name}</h2>
  <div class="card stCard">
    <p><b class="pos-${p.pos}">${p.name}</b> <span class="small">${G.season-p.by}세 · ${PERS_N[p.pers||0]} · ${abilityStars(p)}</span></p>
    <p class="small">행선지 <b style="color:#fff;font-weight:800">${b.name}</b> · 제시 ${P.fee}억
      · 감독 호감도 <b style="color:${A.c};font-weight:800">${A.ic} ${A.t}</b></p>
    <div class="stSay">💬 ${p.name}: ${(REF_SAY[P.why]||REF_SAY.cond)(p,b)}</div>
  </div>
  <div class="card stCard"><h3>한 번 더 설득해 보시겠습니까?</h3>${btns}
    <button class="mini" style="display:block;width:100%;padding:9px;margin-top:4px" onclick="persuadeGiveUp()">그만둔다 (이적 무산)</button>
  </div>`;
  window.scrollTo(0,0);
}
function persuadeGiveUp(){
  const P=PERSU; const _b=persuadeBack(); PERSU=null;
  if(P){ G.offers=G.offers.filter(o=>!(o.pid===P.pid&&o.tid===P.tid)); if(G.snego&&G.snego.pid===P.pid) G.snego=null; }
  saveGame(); show(_b);
}
function persuadePick(i){
  const P=PERSU; if(!P) return;
  const t=userTeam(), p=t.players.find(x=>x.id===P.pid), b=G.teams[P.tid];
  const o=PERSUADE[i]; if(!o||!p||!b) return;
  /* ⚠ "설득이 너무 쉽다" — 이 선수는 방금 이적을 '거절한' 선수다.
     떠나고 싶은 마음(want)을 그대로 다시 굴리면 한 번 더 물어보는 것만으로 반이 넘어갔다.
     이미 거절한 사람의 마음은 그보다 낮은 곳에서 시작하고, 천장도 둔다. */
  const base=moveRefusal(p, b).want * 0.55;
  let chance = base + (o.k[P.why]||0);
  chance += (aff(p)-50)*0.18*(i===3?1:-1);      // "좋게 보내주겠다"만 호감도가 높을수록 잘 통한다
  if(p.pers===1 && i===0) chance+=10;           // 야심가에게는 커리어 이야기가 먹힌다
  if(p.pers===2 && i===1) chance-=12;           // 온화한 선수에게 냉정하게 굴면 역효과
  if(p.pers===3 && i===1) chance-=15;
  if(P.why==="noMove") chance=Math.min(chance, 22);          // 잔류 선언까지 한 선수는 벽이 다르다
  if((p._persFail||0)>=1) chance-=10*(p._persFail);          // 전에도 밀어냈던 감독의 말은 가볍다
  chance=clamp(chance, 3, 78);
  const ok=Math.random()*100 < chance;
  let msg, cls, extra="";
  if(ok){
    msg=o.ok(p); cls="good";
    p.noMove=false; p._persuaded=true;
    const done=completeSale(P.pid, P.tid, P.fee, P.swapPid);
    extra = done ? "이적이 성사됐습니다." : "협상은 통과했지만 계약이 마무리되지 않았습니다.";
    /* 남기 싫다는 사람을 결국 보냈다 — 동료들이 그 장면을 기억한다 */
    if(done && i===1){
      const t2=userTeam(); t2.morale=Math.round(clamp((t2.morale||70)-1.5,40,99)*100)/100;
      addMood(`😶 ${p.name}이(가) 떠났습니다. "자리가 없다"는 말이 라커룸에 남았습니다.`);
    }
  } else {
    msg=o.no(p); cls="warn";
    affAdd(p, o.af, "이적 설득 실패");
    p._persFail=(p._persFail||0)+1;
    p.morale=Math.round(clamp(p.morale-5,25,99)*100)/100;
    if(o.af<=-10){ p.unhappy=Math.min(3,(p.unhappy||0)+1); p.morale=Math.round(clamp(p.morale-3,25,99)*100)/100; }
    /* 온화한 선수에게 "네 자리는 없다"고 말하면 상처가 오래 간다 */
    if(p.pers===2 && i===1){ affAdd(p, -6, "냉정한 통보"); addMood(`💔 ${p.name}이(가) 면담 후 말없이 짐을 챙겨 먼저 퇴근했습니다.`); }
    /* 🔥 태업 — 나가기 싫다는 사람을 계속 밀어내면 결국 터진다.
       다혈질, 불만이 쌓인 선수, 이미 한 번 밀어냈던 선수일수록 위험하다. */
    const sulkP = (o.af<=-10 ? 0.25 : 0.08)
      + (p.pers===3 ? 0.30 : 0)
      + ((p.unhappy||0)>=2 ? 0.25 : 0)
      + ((p._persFail||0)>=2 ? 0.20 : 0);
    if(Math.random() < sulkP){
      p.sulk=3+R(3); p.morale=35; p.uWhy="강제 이적 시도"; p.unhappy=Math.min(3,(p.unhappy||0)+1);
      if(G.staff && G.staff.handled) delete G.staff.handled[p.id];
      notify(`🔥 <b>태업 돌입!</b> ${p.name}: "나가기 싫다는 사람을 왜 자꾸 미시는 겁니까!" — 훈련 거부 (${p.sulk}라운드 결장, 스태프 회의에서 면담 가능)`,"warn");
      addMood(`🔥 ${p.name}이(가) 훈련장에 나오지 않습니다. 라커룸 공기가 무겁습니다.`);
      const t2=userTeam(); t2.morale=Math.round(clamp((t2.morale||70)-2,40,99)*100)/100;
      extra=`<b style="color:var(--red)">태업에 들어갔습니다.</b> ${p.sulk}라운드 동안 뛰지 않습니다.`;
    } else {
      extra=`${p.name}은(는) 당분간 이적을 거부합니다. (호감도 ${o.af>0?"+":""}${o.af}${(p.unhappy||0)>0?` · 불만 ${p.unhappy}/3`:""})`;
      /* 라커룸도 듣는다 — 동료를 떠밀어내려 한 이야기는 돈다 */
      if(o.af<=-10 && Math.random()<0.4) addMood(`👂 ${p.name} 면담 이야기가 라커룸에 돌고 있습니다. 몇몇이 눈치를 봅니다.`);
    }
    /* ⚠ 제보 — 「선수 본인이 이적하고 싶대서 이적명단 올렸는데 막상 협상하니
       남고싶다고 잔류선언 해버리는 게 골때림」. 설득 실패가 무조건 잔류 선언(noMove)으로
       굳었다. 공개적으로 나가겠다던 선수가 (전력이 크게 처지는) 한 구단을 거절했다고
       「아무 데도 안 간다」가 되는 건 앞뒤가 안 맞는다 — 이적 요청 중이면 그 구단 제안만
       접고 요청 상태는 유지한다. */
    if(!wantsOut(p)) p.noMove=true;             // 한 번 버틴 선수는 당분간 요지부동 (이적 요청 중이면 예외)
    G.offers=G.offers.filter(x=>!(x.pid===P.pid&&x.tid===P.tid));
    if(G.snego&&G.snego.pid===P.pid) G.snego=null;
  }
  const _bk=persuadeBack();
  PERSU=null;
  const cont = ok ? (()=>runPendingBye(()=>show(_bk))) : (()=>show(_bk));
  $("#main").innerHTML=`<h2>🤝 이적 설득 — ${p.name}</h2>
  <div class="card stCard">
    <p>🗣️ 감독: "${o.t}"</p>
    <p style="color:var(--acc)">💬 ${p.name}: ${msg}</p>
    <div class="msg ${cls}">설득 ${ok?"성공":"실패"} (성공 확률 ${Math.round(chance)}%) · ${extra}</div>
  </div>
  <div class="card"><button class="mini" style="width:100%;padding:11px" onclick="(${ok?`()=>runPendingBye(()=>show('${_bk}'))`:`()=>show('${_bk}')`})()">확인 ▶</button></div>`;
  saveGame(); window.scrollTo(0,0);
}
/* ── 상대 구단이 협상 자체를 거부한다 ─────────────────────────
   핵심 선수는 돈으로 살 수 없다. 이적시장 마감이 가까울수록, 순위 경쟁 중일수록 더 완강하다. */
function clubRefusesToSell(from, p){
  if(p && p.army && p.army.out) return `"${p.name} 선수는 군 복무 중입니다. 전역 전에는 어떤 이야기도 불가능합니다."`;
  const core = p.ovr >= teamOVR(from)+0.5;   // 예전에는 +1.5 — 어지간한 주전은 다 팔렸다
  if(!core) return null;
  const tbl=tableOf(from.div), pos=tbl.findIndex(x=>x.id===from.id)+1;
  let hard = 30;
  hard += (p.ovr - teamOVR(from))*6;
  if(pos<=3) hard += 20;                        // 우승 경쟁 중
  if(pos>=tbl.length-3) hard += 12;             // 강등 싸움 중 — 전력을 뺄 수 없다
  if((p.ct||1)>=3) hard += 22;                  // 장기 계약
  /* ⚠ 제보 — 계약 1년(−30)과 31세 이상(−15)이 겹치면 어느 팀에서든 주축을 데려올 수 있었다.
     노장 헐값 영입이 사실상 무제한이 되던 경로다. 폭을 줄이고 최소 거부선을 둔다. */
  if((p.ct||1)<=1) hard -= 20;                  // 계약 만료 임박 — 오히려 팔고 싶다
  if(G.season-p.by>=31) hard -= 9;
  if(p.unhappy>0) hard -= 25;                   // 본인이 나가고 싶어 한다
  const w=windowInfo();
  if(w.open && w.left!=null && w.left<=7) hard += 10;   // 마감 직전엔 대체자를 못 구한다
  const wOpen=windowInfo();
  if(wOpen.name==="여름") hard += 12;           // 시즌 중에 주축을 빼는 건 더 어렵다
  /* 핵심 자원(core)을 내주는 데는 최소한의 저항이 있다 — 조건이 아무리 좋아도 그냥은 안 판다.
     본인이 나가고 싶어 하는 경우에만 그 바닥이 낮아진다. */
  const floor = p.unhappy>0 ? 6 : 18;
  hard=clamp(hard, floor, 95);
  if(Math.random()*100 >= hard) return null;
  return pick([
    `"${p.name}은 비매품입니다. 어떤 금액도 의미 없습니다."`,
    `"그 선수는 우리 팀의 중심입니다. 협상 자체를 하지 않겠습니다."`,
    `"시즌 중에 핵심 선수를 내주는 구단이 어디 있습니까. 다음에 얘기하시죠."`,
    `"${p.name}이요? 저희도 지켜야 할 게 있습니다. 죄송합니다."`
  ]);
}
/* ═══════════════════════════════════════════════════════════════
   🪑 경질 — 이 게임의 게임 오버
   FM처럼 한 번에 자르지 않는다. 구단주 신뢰가 무너지면 경고가 오고,
   그래도 반등하지 못하면 최후통첩이 붙는다. 통첩 기간 안에 결과를 내지 못하면 경질이다.
     · 경고    (구단주 32 미만)  — 뉴스와 팝업으로 통보, 아직 여유가 있다
     · 최후통첩(구단주 20 미만)  — 남은 5경기 안에 승점 7 이상을 따야 한다
     · 즉시 경질(구단주 8 이하 또는 통첩 실패, 또는 구단주 18 미만 + 팬 18 미만)
   시즌 초반 5라운드는 유예 기간이다 — 부임하자마자 잘리지는 않는다.
   ═══════════════════════════════════════════════════════════════ */
const SACK_WARN=32, SACK_ULTI=20, SACK_NOW=8, SACK_GRACE=5;
const SACK_ULTI_ROUNDS=5, SACK_ULTI_PTS=7;
/* ⚠ 통첩을 넘긴 뒤에도 신뢰가 통첩선(20) 아래에 머물면 다음 경기 한 번 지자마자
   또 통첩이 날아왔다 — "7점 따도 무한 반복". 그래서 두 가지를 둔다.
     ① 살아남으면 신뢰를 통첩선이 아니라 경고선 위(38+)까지 확실히 끌어올린다
     ② 그 위에 추가로 유예 라운드를 둔다 — 이 기간에는 통첩을 다시 걸지 않는다 */
const SACK_ULTI_COOL=8;
function boardState(){
  if(!G.board) G.board={stage:0, ultiFrom:null, ultiPts:0, warned:0, ultiCool:0, ultiSaved:0};
  if(typeof G.board.ultiCool!=="number") G.board.ultiCool=0;
  if(typeof G.board.ultiSaved!=="number") G.board.ultiSaved=0;
  return G.board;
}
function sackCheck(){
  const t=userTeam(); if(!t) return false;
  if(G.jobless) return false;
  if(G.phase==="sacked" || G.phase==="seasonEnd") return false;
  if(!G.trust) return false;
  const b=boardState();
  const rd=t.div===1?G.r1:G.r2;
  if(rd-(G.hiredAtR||0)<SACK_GRACE) return false;   // 부임 직후 유예 (중도 부임이면 그 라운드부터 센다)
  // ── 공언한 시즌 목표와 실제 순위의 괴리 — 구단주는 이걸 가장 크게 본다
  if(G.goal && rd>=8 && rd%2===0){
    const pos=tableOf(t.div).findIndex(x=>x.isUser)+1;
    const miss=pos-G.goal.req;
    const total=(t.div===1?G.k1Fix:G.k2Fix).length||33;
    const late=1+clamp((rd-total*0.5)/total, 0, 0.6);   // 시즌이 갈수록 변명이 통하지 않는다
    if(miss>=4)       adjustTrust("owner", -clamp(miss*0.30, 0.6, 2.8)*late, `시즌 목표(${G.goal.n}) 미달 — 현재 ${pos}위`);
    /* ⚠ 제보 — 「잔류가 목표였는데 2위를 하고도 경질됐다」.
       목표를 크게 넘어서고 있어도 회복이 +0.9뿐이라, 다른 경로로 깎이는 속도를 못 따라갔다.
       넘어선 폭만큼 돌려준다 — 잘하고 있으면 구단주도 그만큼 마음을 놓는다. */
    else if(miss<=-2) adjustTrust("owner", +0.9 + clamp((-miss)*0.28, 0, 2.6), `목표 초과 달성 — 현재 ${pos}위 (목표 ${G.goal.req}위)`);
  }
  const own=G.trust.owner, fan=G.trust.fans;
  /* 🛡️ 성적 방패 — 목표를 넉넉히 넘고 있거나 리그 상위권이면 자르지 않는다.
     2위를 달리는 감독을 경질하는 구단은 없다. 신뢰는 신뢰대로 깎이되(사건의 대가는 남는다),
     경고·통첩·경질만 보류한다. 순위가 떨어지면 그때부터 다시 적용된다. */
  const _shield=(function(){
    try{
      const tb=tableOf(t.div); const pos=tb.findIndex(x=>x.isUser)+1;
      if(pos<=0) return false;
      if(pos<=Math.max(2, Math.round(tb.length*0.18))) return true;   // 리그 상위권
      if(G.goal && pos<=G.goal.req-2) return true;                    // 공언한 목표보다 두 계단 이상 앞
      return false;
    }catch(e){ return false; }
  })();
  // ── 최후통첩 진행 중이면 성적부터 확인한다
  if(b.stage===2 && b.ultiFrom!=null){
    const played=rd-b.ultiFrom;
    const got=t.Pts-b.ultiPts;
    if(got>=SACK_ULTI_PTS){                     // 살아남았다
      b.stage=0; b.ultiFrom=null; b.warned=0;
      b.ultiSaved=(b.ultiSaved||0)+1;
      b.ultiCool=rd+SACK_ULTI_COOL;             // 이 라운드까지는 다시 통첩하지 않는다
      /* 목표치를 넘긴 만큼 더 크게 올린다. 최소한 경고선(32) 위로는 올려 줘야
         다음 경기 한 번 졌다고 곧바로 통첩이 재발하지 않는다. */
      const lift=Math.round(Math.max(SACK_WARN+6-own, 12+(got-SACK_ULTI_PTS)*1.5)*10)/10;
      adjustTrust("owner", lift, `최후통첩 기간 반등 (${played}경기 승점 ${got})`);
      adjustTrust("fans", 5, "최후통첩 기간 반등");
      t.morale=clamp((t.morale||70)+4, 40, 99);
      addNews(`🪑 구단주: "일단 지켜보겠습니다." — 최후통첩이 해제됐습니다. (${played}경기 승점 ${got})`);
      boardModal("🤝 최후통첩 해제",
        `<b>"약속은 지키셨군요."</b><br><br>
         ${played}경기에서 <b>승점 ${got}</b>을 따내며 자리를 지켰습니다.<br>
         구단주 신뢰가 <b style="color:var(--green)">${Math.round(own)} → ${Math.round(G.trust.owner)}</b>으로 회복됐고,
         앞으로 <b>${SACK_ULTI_COOL}라운드</b> 동안은 다시 통첩을 보내지 않겠다는 뜻을 전해 왔습니다.<br><br>
         <span class="small">다만 이 기간에도 성적이 무너지면 경고는 다시 나옵니다.</span>`, "");
      saveGame();
      return false;
    }
    if(played>=SACK_ULTI_ROUNDS){ doSack(`최후통첩 실패 (${played}경기 승점 ${got})`); return true; }
    /* 통첩 기간에는 약속한 ${SACK_ULTI_ROUNDS}경기를 끝까지 준다 — 도중에 신뢰가 더 떨어져도 자르지 않는다 */
    return false;
  }
  // ── 서포터 시위 — 팬 신뢰가 바닥을 기면 경기장 밖에서 먼저 터진다.
  //    (도움말에 "서포터 시위 등 후폭풍"이라 적어 두고 실제로는 아무 일도 없었다)
  if(fan<15 && rd>=SACK_GRACE && (b.protestR==null || rd-b.protestR>=6)){
    b.protestR=rd;
    const t2=userTeam();
    const kind = fan<8 ? 2 : 1;   // 8 미만이면 수위가 다르다
    addNews(kind===2
      ? `📢 <b>${t2.name} 서포터즈, 홈경기 단체 보이콧 선언</b> — "이 구단에 더 쓸 마음이 없다." 트럭 시위까지 예고했습니다.`
      : `📢 ${t2.name} 서포터즈, 경기장 앞 침묵 시위 — 걸개에는 감독과 구단을 향한 요구가 적혔습니다.`, "warn", "club",
      {cat:"club", ic:"📢", tone:-1, tid:t2.id, src:"K리그 공식",
       head:kind===2?`${t2.short} 서포터즈 보이콧 선언`:`${t2.short} 서포터즈 시위`,
       sub:`팬 신뢰가 ${Math.round(fan)}까지 떨어진 상황. 홈 관중과 라커룸 분위기에 그대로 번진다.`});
    try{ socialFill(SOC.protest, 4+R(3), -1, {t:t2.short}); fmkFill(FMK.protest, 3+R(2), {t:t2.short}); }catch(e){}
    try{ bumpHype(t2, kind===2?-0.14:-0.08, "서포터 시위"); }catch(e){}
    t2.morale=Math.round(clamp((t2.morale||70)-(kind===2?3:2),40,99)*100)/100;
    try{ addMood(kind===2?`📢 서포터즈가 보이콧을 선언했습니다. 텅 빈 응원석을 상상하니 선수들 표정이 어둡습니다.`:`📢 경기장 앞 시위 소식이 라커룸까지 들려왔습니다.`); }catch(e){}
    adjustTrust("owner", -3, "서포터 시위 사태");
  }
  // ── 즉시 경질 조건
  if(_shield){
    /* 성적으로 버티는 중 — 경고 단계만 되돌려 두고 넘어간다 */
    if(b.stage>0 && own>=SACK_ULTI){ b.stage=0; b.ultiFrom=null; }
    return false;
  }
  if(own<=SACK_NOW){ doSack("구단주 신뢰 완전 상실"); return true; }
  if(own<18 && fan<18){ doSack("구단주·서포터 모두에게 신뢰를 잃음"); return true; }
  // ── 최후통첩 (직전 통첩을 넘겼다면 유예 라운드가 끝난 뒤에야 다시 온다)
  if(own<SACK_ULTI && b.stage<2 && rd>=(b.ultiCool||0)){
    b.stage=2; b.ultiFrom=rd; b.ultiPts=t.Pts;
    addNews(`🚨 구단주가 감독에게 최후통첩을 보냈습니다 — 남은 ${SACK_ULTI_ROUNDS}경기에서 승점 ${SACK_ULTI_PTS} 이상이 필요합니다.`);
    boardModal("🚨 최후통첩",
      `구단주실에서 호출이 왔습니다.<br><br>
       <b>"감독님, 더는 기다릴 수 없습니다."</b><br><br>
       앞으로 <b>${SACK_ULTI_ROUNDS}경기</b> 안에 <b>승점 ${SACK_ULTI_PTS}점</b> 이상을 따내지 못하면
       계약을 해지하겠다는 통보입니다.`, "danger");
    return false;
  }
  // ── 경고
  if(own<SACK_WARN && b.stage<1){
    b.stage=1; b.warned=(b.warned||0)+1;
    addNews(`⚠️ 구단주가 최근 성적에 강한 불만을 표시했습니다. (구단주 신뢰 ${Math.round(own)})`);
    boardModal("⚠️ 구단주 경고",
      `<b>"이런 흐름이 계속되면 서로 곤란해집니다."</b><br><br>
       구단주가 최근 성적을 두고 우려를 전했습니다.
       지금부터 결과를 내지 못하면 최후통첩으로 이어질 수 있습니다.<br><br>
       <span class="small">구단주 신뢰 ${Math.round(own)} · 서포터 신뢰 ${Math.round(fan)}</span>`, "");
    return false;
  }
  if(own>=SACK_WARN+8 && b.stage===1){ b.stage=0; }   // 회복하면 경고가 풀린다
  /* 유예 기간에 다시 무너지면 통첩 대신 경고를 한 번 더 보낸다 — 아무 신호 없이 잘리지는 않게 */
  if(own<SACK_ULTI && b.stage===1 && rd<(b.ultiCool||0) && rd!==b.warnRd){
    b.warnRd=rd;
    addNews(`⚠️ 구단주: "지난번 약속을 잊은 건 아니겠죠." — 성적이 다시 통첩 수준으로 떨어졌습니다. (구단주 신뢰 ${Math.round(own)})`);
  }
  return false;
}
function boardModal(title, body, cls){
  /* 🪑 ⚠ 제보 — 「구단한테 짤리기 직전이라고 경고는 받았지만 짤리진 않았는데 진행이 안 됨」
     (파주 2031 세이브 분석 — 세이브 자체는 멀쩡했다).
     ─ 원인: 이 모달과 진행 상자·확인창이 전부 #gcModal 한 칸을 나눠 쓰고, 「알겠습니다」가
       show(VIEW) 로 화면을 통째로 다시 그린다. 경기 직후 라커룸 토크·기자회견이 아직 진행
       중일 때 경고 모달이 뜨면 — 닫는 순간 그 화면이 지워지는데 진행 표식(inLockerTalk·IV…)은
       남는다 → progBusy() 가 영원히 참 → 진행 버튼이 눌러도 조용히 무시된다.
     ─ 바쁜 동안(경기·회견·라커룸·진행 상자)에는 모달을 미뤄 두고(G._boardMsg), 알림만 남긴다.
       한가해지면 show() 끝의 boardFlush() 가 띄운다. 닫을 때도 바쁘면 화면을 다시 그리지 않는다. */
  try{
    const busy = (typeof progBusy==="function" && progBusy())
              || (typeof liveM!=="undefined" && liveM)
              || (typeof PROG!=="undefined" && PROG);
    if(busy){
      G._boardMsg={t:String(title), b:String(body), c:cls||""};
      try{ notify(`${title} — 구단주실에서 연락이 왔습니다. 하던 일이 끝나면 안내가 뜹니다.`,"warn"); }catch(e){}
      /* 🪑 ⚠ 제보 — 「구단 프런트에 제안하고 거절당했을 때 거절 팝업이 뜨지 않는다」.
         미뤄 둔 안내는 show() 끝의 boardFlush() 에만 기대고 있었다. 화면을 옮기지 않으면
         (제안 → 결과처럼 그 자리에서 끝나는 흐름) 영영 뜨지 않는다.
         ─ 스스로 지켜보다가 한가해지는 순간 띄운다. 30초 안에 못 띄우면 포기하지 않고
           남겨 두어 다음 화면 전환에서 boardFlush 가 처리한다. */
      try{
        if(!G._boardTry){
          let n=0;
          G._boardTry=setInterval(()=>{
            try{
              if(!G || !G._boardMsg || ++n>60){ clearInterval(G._boardTry); G._boardTry=null; return; }
              boardFlush();
            }catch(_){ try{ clearInterval(G._boardTry); }catch(__){} G._boardTry=null; }
          }, 500);
        }
      }catch(e){}
      return;
    }
    try{ if(G._boardTry){ clearInterval(G._boardTry); G._boardTry=null; } }catch(e){}
  }catch(e){}
  const box=$("#gcModal"); if(!box) return;
  box.className="";
  box.innerHTML=`<div class="gcOverlay"><div class="gcBox">
    <div class="gcBody"><h3 style="margin-top:0">${title}</h3>${body}</div>
    <div class="gcBtns"><button class="gcOk${cls==="danger"?" danger":""}">알겠습니다</button></div>
  </div></div>`;
  // 모달을 닫으면 지금 보고 있는 화면을 다시 그린다. 이게 없으면 예산 증액 요청 뒤에
  // "2/3회" 같은 숫자가 그대로 남아 있다가, 다른 탭에 다녀와야 갱신됐다.
  // ⚠ 단, 회견·라커룸이 돌고 있으면 다시 그리지 않는다 — 그 화면을 부수면 진행이 멈춘다 (제보).
  box.querySelector(".gcOk").onclick=()=>{ box.className="hidden"; box.innerHTML="";
    const busy2=(typeof progBusy==="function" && progBusy());
    if(typeof VIEW!=="undefined" && VIEW && !liveM && !busy2){ try{ show(VIEW); }catch(e){} } };
}
/* 미뤄 둔 구단주 모달 — 한가해진 순간에 띄운다 (show() 끝에서 부른다) */
function boardFlush(){
  try{
    if(!G || !G._boardMsg) return;
    if(typeof progBusy==="function" && progBusy()) return;
    if(typeof liveM!=="undefined" && liveM) return;
    if(typeof PROG!=="undefined" && PROG) return;
    const m=G._boardMsg; G._boardMsg=null;
    boardModal(m.t, m.b, m.c);
  }catch(e){}
}
/* 경질 확정 */
